const $=id=>document.getElementById(id);
let csrf='',storyItems=[];
let editorMap=null,editorMarker=null,editorMapLoad=null;
function editorCoordinates(){const lat=Number($('latitude').value),lon=Number($('longitude').value);return $('latitude').value!==''&&$('longitude').value!==''&&Number.isFinite(lat)&&Number.isFinite(lon)&&Math.abs(lat)<=90&&Math.abs(lon)<=180?[lat,lon]:null}
function positionEditorMarker(point){if(!editorMap)return;if(editorMarker)editorMarker.setLatLng(point);else{editorMarker=window.L.marker(point,{draggable:true}).addTo(editorMap);editorMarker.on('dragend',()=>applyEditorPoint(editorMarker.getLatLng()))}}
function applyEditorPoint(point){$('latitude').value=Number(point.lat).toFixed(5);$('longitude').value=Number(point.lng).toFixed(5);positionEditorMarker([Number($('latitude').value),Number($('longitude').value)]);$('map-status').textContent='Ponto selecionado. Ajuste o marcador ou as coordenadas antes de salvar.'}
function loadEditorMap(){if(editorMapLoad)return editorMapLoad;editorMapLoad=new Promise((resolve,reject)=>{const css=document.createElement('link');css.rel='stylesheet';css.href='https://cdn.jsdelivr.net/npm/leaflet@1.9.4/dist/leaflet.css';css.onerror=()=>reject(Error('Mapa indisponível. Digite as coordenadas manualmente.'));document.head.append(css);const script=document.createElement('script');script.src='https://cdn.jsdelivr.net/npm/leaflet@1.9.4/dist/leaflet.js';script.onload=()=>window.L?resolve(window.L):reject(Error('Mapa indisponível. Digite as coordenadas manualmente.'));script.onerror=()=>reject(Error('Mapa indisponível. Digite as coordenadas manualmente.'));document.head.append(script)}).catch(error=>{editorMapLoad=null;throw error});return editorMapLoad}
async function toggleEditorMap(){if(!$('admin-map').hidden){$('admin-map').hidden=true;$('pick-location').setAttribute('aria-expanded','false');$('pick-location').textContent='Escolher no mapa';return}$('map-status').textContent='Carregando mapa…';try{const L=await loadEditorMap();if($('story-form').hidden)return;$('admin-map').hidden=false;$('pick-location').setAttribute('aria-expanded','true');$('pick-location').textContent='Ocultar mapa';const point=editorCoordinates();if(!editorMap){editorMap=L.map('admin-map',{maxZoom:19}).setView(point||[-25.428,-49.273],point?12:3);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener noreferrer">OpenStreetMap</a> contributors'}).addTo(editorMap);editorMap.on('click',event=>applyEditorPoint(event.latlng))}editorMap.invalidateSize();editorMap.setView(point||[-25.428,-49.273],point?Math.max(12,editorMap.getZoom()):3);if(point)positionEditorMarker(point);else if(editorMarker){editorMap.removeLayer(editorMarker);editorMarker=null}$('map-status').textContent='Clique no mapa para marcar a história. Você pode arrastar o marcador.'}catch(error){$('map-status').textContent=error.message}}
function message(value){$('status').textContent=value}
async function api(path,options={}){
 if(location.protocol==='file:')throw Error('Abra esta página em http://localhost:8000/admin/ após iniciar o servidor Node.');
 let response;
 try{response=await fetch(path,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(csrf?{'X-CSRF-Token':csrf}:{})},...options})}
 catch{throw Error('Não foi possível conectar ao servidor. Inicie o Nocturna com o arquivo start-nocturna.cmd.')}
 if(!response.headers.get('Content-Type')?.includes('application/json'))throw Error('Esta página está sendo servida sem a API. Pare o servidor Python e inicie com start-nocturna.cmd.');
 const data=await response.json();
 if(!response.ok){const error=Error(data.error||'Erro na solicitação');error.status=response.status;throw error}
 return data;
}
function field(tag,text,id){const label=document.createElement('label');label.textContent=text;const input=document.createElement(tag);input.id=id;input.required=true;if(tag==='textarea'&&id.endsWith('-body'))input.className='body';label.append(input);return label}
for(const [locale,name] of [['pt','Português'],['en','English'],['es','Español']]){const section=document.createElement('section');section.className='admin-translations';const heading=document.createElement('h3');heading.textContent=name;section.append(heading,field('input','Título',locale+'-title'),field('textarea','Resumo',locale+'-summary'),field('textarea','Texto',locale+'-body'));$('translations').append(section)}
const sourceBlock=$('source-title').closest('.admin-pair');const sourceExtras=document.createElement('div');sourceExtras.className='admin-link-list';const addSource=makeButton('Adicionar fonte',()=>sourceExtras.append(sourceRow()));sourceBlock.after(sourceExtras,addSource);const exploreSection=document.createElement('section');exploreSection.className='admin-links';const exploreHeading=document.createElement('h3');exploreHeading.textContent='Explorar além da história';const exploreHelp=document.createElement('p');exploreHelp.className='admin-help';exploreHelp.textContent='Inclua documentos, imagens, áudios, vídeos ou leituras externas. Esses links são complementares e não comprovam, por si só, as alegações da história.';const exploreList=document.createElement('div');exploreList.className='admin-link-list';const addExplore=makeButton('Adicionar link de exploração',()=>exploreList.append(exploreRow()));exploreSection.append(exploreHeading,exploreHelp,exploreList,addExplore);addSource.insertAdjacentElement('afterend',exploreSection);
function sourceRow(source={}){const row=document.createElement('div');row.className='admin-pair admin-link-row';const title=field('input','Título da fonte','');title.querySelector('input').className='source-title';title.querySelector('input').value=source.title||'';const url=field('input','URL da fonte (HTTPS)','');url.querySelector('input').className='source-url';url.querySelector('input').type='url';url.querySelector('input').placeholder='https://...';url.querySelector('input').value=source.url||'';row.append(title,url,makeButton('Remover fonte',()=>row.remove()));return row}
function exploreRow(item={}){const row=document.createElement('div');row.className='admin-link-row';const kind=field('select','Tipo','');kind.querySelector('select').className='explore-kind';for(const [value,label] of [['document','Documento'],['image','Imagem'],['audio','Áudio'],['video','Vídeo'],['reading','Leitura']]){const option=document.createElement('option');option.value=value;option.textContent=label;kind.querySelector('select').append(option)}kind.querySelector('select').value=item.kind||'document';const url=field('input','URL (HTTPS)','');url.querySelector('input').className='explore-url';url.querySelector('input').type='url';url.querySelector('input').placeholder='https://...';url.querySelector('input').value=item.url||'';const labels=document.createElement('div');labels.className='admin-pair';for(const [lang,label] of [['pt','Título em português'],['en','Title in English'],['es','Título en español']]){const entry=field('input',label,'');entry.querySelector('input').className='explore-label-'+lang;entry.querySelector('input').value=item.labels?.[lang]||'';labels.append(entry)}row.append(kind,url,labels,makeButton('Remover link',()=>row.remove()));return row}
function setSources(sources=[]){$('source-title').value=sources[0]?.title||'';$('source-url').value=sources[0]?.url||'';sourceExtras.replaceChildren();for(const source of sources.slice(1))sourceExtras.append(sourceRow(source))}
function readSources(){const pairs=[[ $('source-title').value.trim(),$('source-url').value.trim() ],...Array.from(sourceExtras.querySelectorAll('.admin-link-row')).map(row=>[row.querySelector('.source-title').value.trim(),row.querySelector('.source-url').value.trim()])];const sources=[];for(const [title,url] of pairs){if(!title&&!url)continue;if(!title||!url)return {error:'Preencha o título e a URL de cada fonte juntos.'};sources.push({title,url})}return {sources}}
function setExplore(items=[]){exploreList.replaceChildren();for(const item of items)exploreList.append(exploreRow(item))}
function readExplore(){const explore=[];for(const row of exploreList.querySelectorAll('.admin-link-row')){const kind=row.querySelector('.explore-kind').value,url=row.querySelector('.explore-url').value.trim(),labels=Object.fromEntries(['pt','en','es'].map(lang=>[lang,row.querySelector('.explore-label-'+lang).value.trim()]));if(!url&&!labels.pt&&!labels.en&&!labels.es)continue;if(!url||!labels.pt||!labels.en||!labels.es)return {error:'Preencha a URL e os três títulos de cada link de exploração.'};explore.push({kind,url,labels})}return {explore}}
function clearForm(story){$('story-form').reset();$('story-form').hidden=false;$('admin-map').hidden=true;$('pick-location').textContent='Escolher no mapa';$('pick-location').setAttribute('aria-expanded','false');$('map-status').textContent='Selecione um ponto aproximado; ele será mostrado aos visitantes.';$('form-title').textContent=story?'Editar história':'Nova história';$('slug').readOnly=!!story;const today=new Date().toISOString().slice(0,10);$('published-at').value=story?.publishedAt||today;$('updated-at').value=today;setSources(story?.sources||[]);setExplore(story?.explore||[]);
 if(!story)return;$('slug').value=story.slug;$('story-status').value=story.status;$('classification').value=story.classification;$('city').value=story.place.city;$('region').value=story.place.region;$('country').value=story.place.country;$('latitude').value=story.place.latitude;$('longitude').value=story.place.longitude;$('event-date').value=story.eventDate||'';for(const lang of ['pt','en','es'])for(const key of ['title','summary','body'])$(lang+'-'+key).value=story.translations?.[lang]?.[key]||''}
function makeButton(text,action){const button=document.createElement('button');button.type='button';button.textContent=text;button.addEventListener('click',action);return button}
async function refresh(){const [stories,comments]=await Promise.all([api('/api/admin/stories'),api('/api/admin/comments')]);storyItems=stories.stories;const list=$('story-list');list.replaceChildren();if(!storyItems.length)list.textContent='Nenhuma história editorial cadastrada.';for(const story of storyItems){const row=document.createElement('div');row.className='admin-row';const text=document.createElement('div');const name=document.createElement('strong');name.textContent=story.translations?.pt?.title||story.slug;const small=document.createElement('small');small.textContent=`${story.status} · ${story.classification} · ${story.slug}`;text.append(name,small);row.append(text,makeButton('Editar',()=>clearForm(story)));list.append(row)}
 const commentList=$('comment-list');commentList.replaceChildren();if(!comments.comments.length)commentList.textContent='Nenhum comentário recebido.';for(const comment of comments.comments){const row=document.createElement('div');row.className='admin-row';const text=document.createElement('div');const name=document.createElement('strong');name.textContent=comment.author;const small=document.createElement('small');small.textContent=`${comment.slug} · ${comment.status} · ${new Date(comment.created_at).toLocaleString('pt-BR')}`;const body=document.createElement('p');body.textContent=comment.body;text.append(name,small,body);const actions=document.createElement('div');actions.className='actions';for(const [label,status] of [['Aprovar','approved'],['Rejeitar','rejected']])actions.append(makeButton(label,async()=>{try{await api(`/api/admin/comments/${comment.id}`,{method:'PATCH',body:JSON.stringify({status})});await refresh()}catch(error){message(error.message)}}));actions.append(makeButton('Excluir',async()=>{if(!confirm('Excluir este comentário?'))return;try{await api(`/api/admin/comments/${comment.id}`,{method:'DELETE'});await refresh()}catch(error){message(error.message)}}));row.append(text,actions);commentList.append(row)}}
async function authenticated(){try{csrf=(await api('/api/admin/me')).csrf;$('login-panel').hidden=true;$('workspace').hidden=false;message('');await refresh()}catch(error){$('login-panel').hidden=false;$('workspace').hidden=true;if(error.status!==401)message(error.message)}}
$('login-form').addEventListener('submit',async event=>{event.preventDefault();try{csrf=(await api('/api/admin/login',{method:'POST',body:JSON.stringify({password:$('password').value})})).csrf;$('password').value='';message('');await authenticated()}catch(error){message(error.message)}});
$('logout').addEventListener('click',async()=>{try{await api('/api/admin/logout',{method:'POST',body:'{}'});csrf='';await authenticated()}catch(error){message(error.message)}});
$('new-story').addEventListener('click',()=>clearForm(null));$('cancel-story').addEventListener('click',()=>{$('story-form').hidden=true});
$('pick-location').addEventListener('click',toggleEditorMap);
for(const id of ['latitude','longitude'])$(id).addEventListener('change',()=>{const point=editorCoordinates();if(point&&editorMap&&!$('admin-map').hidden){positionEditorMarker(point);editorMap.panTo(point)}});
$('story-form').addEventListener('submit',async event=>{event.preventDefault();const sourceResult=readSources(),exploreResult=readExplore();if(sourceResult.error||exploreResult.error){message(sourceResult.error||exploreResult.error);return}const story={slug:$('slug').value.trim(),status:$('story-status').value,classification:$('classification').value,place:{city:$('city').value.trim(),region:$('region').value.trim(),country:$('country').value.trim(),latitude:Number($('latitude').value),longitude:Number($('longitude').value)},eventDate:$('event-date').value.trim()||null,publishedAt:$('published-at').value,updatedAt:$('updated-at').value,sources:sourceResult.sources,explore:exploreResult.explore,translations:Object.fromEntries(['pt','en','es'].map(lang=>[lang,Object.fromEntries(['title','summary','body'].map(key=>[key,$(lang+'-'+key).value.trim()]))]))};try{await api('/api/admin/stories',{method:'POST',body:JSON.stringify(story)});$('story-form').hidden=true;message('História salva.');await refresh()}catch(error){message(error.message)}});
authenticated();
